const $  = (s,c=host)=>c.querySelector(s);
const $$ = (s,c=host)=>Array.from(c.querySelectorAll(s));
const esc = v => String(v==null?'':v).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const today = ()=> new Date().toISOString().slice(0,10);
const now   = ()=> new Date().toISOString();
const num   = v => { const n=parseFloat(v); return isNaN(n)?0:n; };
const money = v => num(v).toLocaleString('pt-BR',{minimumFractionDigits:0,maximumFractionDigits:0})+' FCFA';
const dt = v => {if(!v)return '—';const text=String(v).slice(0,10);if(!/^\d{4}-\d{2}-\d{2}$/.test(text))return esc(v);const p=text.split('-');return p[2]+'/'+p[1]+'/'+p[0];};
const stamp = () => new Date().toLocaleString('pt-PT');
const initials = n => String(n||'?').trim().split(/\s+/).slice(0,2).map(w=>w[0]).join('').toUpperCase();
const nextId = (arr,k) => arr.reduce((m,x)=>Math.max(m,num(x[k])),0)+1;
function nextCode(arr,k,pre,len=3){
  let mx=0;
  arr.forEach(x=>{const m=String(x[k]||'').match(/(\d+)$/); if(m) mx=Math.max(mx,parseInt(m[1]));});
  return pre+String(mx+1).padStart(len,'0');
}
function idade(dn){
  if(!dn) return '—';
  const d=new Date(dn), h=new Date();
  let a=h.getFullYear()-d.getFullYear();
  const m=h.getMonth()-d.getMonth();
  if(m<0 || (m===0 && h.getDate()<d.getDate())) a--;
  return a;
}
function toast(msg,type='ok'){
 if(actionRunning){effects.push(()=>toast(msg,type));return;}
  const icons={ok:'✅',err:'❌',warn:'⚠️',info:'ℹ️'};
  const d=document.createElement('div');
  d.className='toast '+(type==='ok'?'':type);
  d.innerHTML=`<span class="ic">${icons[type]||'ℹ️'}</span><span>${esc(msg)}</span>`;
  $('#toasts').appendChild(d);
  setTimeout(()=>{d.style.transition='.3s';d.style.opacity='0';d.style.transform='translateX(60px)';
    setTimeout(()=>d.remove(),300);},3200);
}
function confirmar(msg, onOk, simLabel='Confirmar', danger=true){
  openModal({
    title:'⚠️ Confirmar Operação', size:'sm',
    body:`<p style="font-size:14px;line-height:1.7">${msg}</p>
      ${danger?'<p style="color:var(--vermelho);font-size:12.5px;margin-top:12px">Esta operação poderá ser irreversível.</p>':''}`,
    buttons:[
      {l:'Cancelar',cls:'btn-ghost',fn:closeModal},
      {l:simLabel,cls:danger?'btn-danger':'btn-primary',fn:()=>{closeModal();return onOk();}}
    ]
  });
}
function openModal({title,sub,body,buttons,size=''}){
  $('#modalRoot').innerHTML=`
    <div class="modal" data-sige-click="${bind((event,element)=>{if(event.target===element)closeModal()})}">
      <div class="modal-box ${size}">
        <div class="modal-head">
          <h3>${esc(title||'')}${sub?`<div style="font-size:12px;color:var(--cinza);font-weight:400;margin-top:3px">${esc(sub)}</div>`:''}</h3>
          <button data-sige-click="${bind((event,element)=>{closeModal()})}">✕</button>
        </div>
        <div class="modal-body">${body||''}</div>
        ${buttons?`<div class="modal-foot">${buttons.map((b,i)=>`<button class="btn ${b.cls||'btn-ghost'}" data-mbtn="${i}">${b.l}</button>`).join('')}</div>`:''}
      </div>
    </div>`;
  if(buttons) buttons.forEach((b,i)=>{ const el=$(`[data-mbtn="${i}"]`); if(el) el.onclick=e=>runAction(()=>b.fn(e)); });
}
function closeModal(){ if(actionRunning){effects.push(closeModal);return;} $('#modalRoot').innerHTML=''; }


