/* ---------- HELPERS DE DOMÍNIO ---------- */
const getAluno = id => DB.alunos.find(a=>a.IdAluno===id);
const getTurma = id => DB.turmas.find(t=>t.CodTurma===id);
const getClasse=(nomeOrId,ano=DB.config.anoActivo)=>{const c=typeof nomeOrId==='number'?DB.classes.find(c=>c.IdClasse===nomeOrId):DB.classes.find(c=>c.Classe===nomeOrId);return c?.PorAno?.[ano]?{...c,...c.PorAno[ano]}:null;};
const getCurso = id => DB.cursos.find(c=>c.CodCurso===id);
const getMateria = id => DB.materias.find(m=>m.IdMateria==id);
const getFunc = id => DB.funcionarios.find(f=>f.IdFuncionario===id);
const getInsc = id => DB.inscricoes.find(i=>i.IdInscricao==id);

function alunosDaTurma(codTurma,ano){
  const t=getTurma(codTurma); if(!t) return [];
  return DB.inscricoes
    .filter(i=>i.CodTurma===codTurma && i.Ano===(ano||t.Ano) && i.Estado==='Matriculado')
    .map(i=>({ins:i,aluno:getAluno(i.CodAluno)}))
    .filter(x=>x.aluno)
    .sort((a,b)=>a.aluno.Nome.localeCompare(b.aluno.Nome));
}
function turmasPermitidas(){
  if(session.Perfil!=='Professor') return DB.turmas;
  const at=DB.atribuicoes.filter(a=>a.CodFuncionario===session.CodFuncionario).map(a=>a.CodTurma);
  return DB.turmas.filter(t=>at.includes(t.CodTurma));
}
function materiasPermitidas(codTurma){
  if(session.Perfil!=='Professor') return DB.materias;
  const at=DB.atribuicoes.filter(a=>a.CodFuncionario===session.CodFuncionario && a.CodTurma===codTurma);
  return DB.materias.filter(m=>at.some(a=>String(a.IdMateria)===String(m.IdMateria)));
}

/* ---------- MOTOR DE AVALIAÇÃO ---------- */
function getNotaReg(codInsc,idMateria,ano){
  return DB.notas.find(n=>String(n.CodInscricao)===String(codInsc) && String(n.CodMateria)===String(idMateria) && n.Ano===(ano||getInsc(codInsc)?.Ano||DB.config.anoActivo));
}
function criarNotaReg(codInsc,idMateria,ano){
  const nova={IdNota:nextId(DB.notas,'IdNota'),CodInscricao:Number(codInsc),CodMateria:Number(idMateria),
    Ano:ano||DB.config.anoActivo,
    I_Trimestre:{MAC:null,NPP:null,NPT:null},
    II_Trimestre:{MAC:null,NPP:null,NPT:null},
    III_Trimestre:{MAC:null,NPP:null,NPT:null},
    ExameFinal:null,ExameRecurso:null,Locked:false,CodProfessor:'',DataLancamento:null};
  DB.notas.push(nova); return nova;
}
function mediaTrimestre(nota,periodoKey){
  if(!nota||!nota[periodoKey]) return null;
  const t=nota[periodoKey];
  const v=[t.MAC,t.NPP,t.NPT].filter(x=>x!==null&&x!==undefined&&x!=='');
  if(!v.length) return null;
  return Math.round(v.reduce((s,x)=>s+num(x),0)/v.length);
}
function mediaAnual(nota){
  if(!nota) return null;
  const ms=PERIODOS.map(p=>mediaTrimestre(nota,p.replace(' ','_'))).filter(v=>v!==null);
  if(!ms.length) return null;
  return Math.round(ms.reduce((a,b)=>a+b,0)/ms.length);
}
function notaFinalDisciplina(nota){
  const ma=mediaAnual(nota); if(ma===null) return null;
  const ef=nota.ExameFinal;
  const pma=DB.config.pesoMediaAnual??0.7;
  const pef=DB.config.pesoExameFinal??0.3;
  if(ef===null||ef===undefined||ef==='') return ma;
  return Math.round(ma*pma + num(ef)*pef);
}
function notaFinalComRecurso(nota){
  const nf=notaFinalDisciplina(nota);
  if(nota.ExameRecurso!==null && nota.ExameRecurso!==undefined && nota.ExameRecurso!==''){
    return Math.max(nf||0, num(nota.ExameRecurso));
  }
  return nf;
}


