function renderView(){
  if(actionRunning&&dirty){needsRender=true;return;}
  const focused=document.activeElement; const focusId=focused?.id; const selection=focused?.selectionStart;
  if(!session) return;
  if(!can(state.view)) state.view='dashboard';
  const el=$('#view'); el.innerHTML='';
  const fn=VIEWS[state.view];
  if(fn){fn(el);groupStudentTables(el);} else el.innerHTML='<div class="card"><div class="vazio">Módulo em construção.</div></div>';
  if(focusId){const restored=host.querySelector('#'+CSS.escape(focusId));if(restored){restored.focus();try{restored.setSelectionRange(selection,selection);}catch{}}} else el.scrollTop=0; queueMicrotask(pruneActions);
}

