function formClasse(id){
  const year=state.ano_classe||DB.config.anoActivo;
  const c=id?DB.classes.find(x=>x.IdClasse===id):null;
  const d=(c?getClasse(id,year):null)||{IdClasse:nextId(DB.classes,'IdClasse'),Classe:'',Inscricao:0,Propina:0,Duracao:12,Valor:0,MaxNegativas:2,NegRecurso:4,NotaRecurso:8,CodEscola:'ESC001'};
  openModal({
    title:c?`✏️ Editar Classe ${c.Classe}`:'➕ Nova Classe',
    sub:'Tarifas e regras do ano '+year, size:'lg',
    body:`<div class="form-grid g2">
      <div class="form-sec">📋 Dados Gerais</div>
      <div class="campo span2"><label>Designação <span class="req">*</span></label>
        <input id="c_Classe" value="${esc(d.Classe)}" placeholder="Ex.: 10ª Classe"></div>
      <div class="campo"><label>Duração (meses)</label>
        <input type="number" id="c_Duracao" value="${d.Duracao||12}" data-sige-input="${bind((event,element)=>{recalcTotalClasse()})}"></div>
      <div class="form-sec">💰 Valores (FCFA)</div>
      <div class="campo"><label>Taxa de Inscrição</label>
        <input type="number" step="1" id="c_Inscricao" value="${d.Inscricao||0}" data-sige-input="${bind((event,element)=>{recalcTotalClasse()})}"></div>
      <div class="campo"><label>Propina Mensal</label>
        <input type="number" step="1" id="c_Propina" value="${d.Propina||0}" data-sige-input="${bind((event,element)=>{recalcTotalClasse()})}"></div>
      <div class="campo span2"><label>Valor Total (Propina × Meses + Inscrição)</label>
        <input type="number" step="1" id="c_Valor" value="${d.Valor||0}" readonly
          style="background:var(--azul4);font-weight:700;color:var(--azul)"></div>
      <div class="form-sec">📊 Regras de Aprovação</div>
      <div class="campo"><label>Máx. Negativas p/ Aprovação</label><input type="number" id="c_MaxNeg" value="${d.MaxNegativas??2}"></div>
      <div class="campo"><label>Negativas p/ Recurso</label><input type="number" id="c_NegRec" value="${d.NegRecurso??4}"></div>
      <div class="campo"><label>Nota Mín. Recurso</label><input type="number" step="1" id="c_NotaRec" value="${d.NotaRecurso??8}"></div>
    </div>`,
    buttons:[
      {l:'Cancelar',cls:'btn-ghost',fn:closeModal},
      {l:'💾 Guardar',cls:'btn-primary',fn:()=>{
        const propina=num($('#c_Propina').value);
        const duracao=num($('#c_Duracao').value)||12;
        const inscricao=num($('#c_Inscricao').value);
        const obj={IdClasse:c?c.IdClasse:nextId(DB.classes,'IdClasse'),
          Classe:$('#c_Classe').value.trim(),Duracao:duracao,
          Inscricao:inscricao,Propina:propina,
          Valor:calcTotalClasse(propina,duracao,inscricao),
          MaxNegativas:num($('#c_MaxNeg').value),NegRecurso:num($('#c_NegRec').value),
          NotaRecurso:num($('#c_NotaRec').value),CodEscola:'ESC001'};
        if(!obj.Classe){ toast('Indique a designação','err'); return; }
        const settings={};for(const key of ['Inscricao','Propina','Duracao','Valor','MaxNegativas','NegRecurso','NotaRecurso'])settings[key]=obj[key];
        if(c){c.Classe=obj.Classe;c.PorAno={...c.PorAno,[year]:settings};toast('Tarifas anuais actualizadas.');}
        else {obj.PorAno={[year]:settings};DB.classes.push(obj);}
        saveDB(); closeModal(); renderView();
      }}
    ]
  });
}
function recalcTotalClasse(){
  const p=num($('#c_Propina').value);
  const m=num($('#c_Duracao').value)||12;
  const i=num($('#c_Inscricao').value);
  $('#c_Valor').value = calcTotalClasse(p,m,i);
}

function apagarClasse(id){
  confirmar('Eliminar esta classe?',()=>{
    DB.classes=DB.classes.filter(c=>c.IdClasse!==id);
    saveDB(); renderView(); toast('Classe eliminada.','warn');
  },'🗑 Eliminar');
}

