function toggleLock(id){
  const a=DB.atribuicoes.find(x=>x.IdAtribuicao===id);
  if(!a) return;
  a.Locked=!a.Locked;
  saveDB(); renderView();
  toast(a.Locked?'Bloqueada.':'Desbloqueada.','info');
}

