/* MINHAS TURMAS */
VIEWS['minhas-turmas'] = el=>{
  if(session.Perfil!=='Professor'){
    el.innerHTML='<div class="card"><div class="vazio">Área para professores.</div></div>'; return;
  }
  const ats=DB.atribuicoes.filter(a=>a.CodFuncionario===session.CodFuncionario && a.Ano===DB.config.anoActivo);
  if(!ats.length){ el.innerHTML='<div class="card"><div class="vazio">Sem turmas atribuídas.</div></div>'; return; }
  const porTurma={}; ats.forEach(a=>{(porTurma[a.CodTurma]=porTurma[a.CodTurma]||[]).push(a);});
  el.innerHTML=`<div class="info-box">
    <b>👨‍🏫 Nota:</b> Pode lançar notas apenas nas suas disciplinas. Após gravar, ficam bloqueadas.
    Tem acesso às suas fichas de avaliação, mas <b>não</b> às pautas gerais nem aos boletins dos alunos.
  </div>
  <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:16px">
    ${Object.keys(porTurma).map(tid=>{
      const t=getTurma(tid); if(!t) return '';
      const c=getCurso(t.Curso);
      const n=alunosDaTurma(tid,t.Ano).length;
      return `<div class="card" style="margin:0">
        <div class="card-head"><h2>🏫 ${esc(t.Turma)} — ${esc(t.Classe)}</h2></div>
        <div class="card-body">
          <div style="font-size:12.5px;color:var(--cinza);line-height:1.9;margin-bottom:10px">
            <div><b>Curso:</b> ${esc(c?c.Nome:'—')}</div>
            <div><b>Turno:</b> ${esc(t.Turno)} · <b>Sala:</b> ${esc(t.Sala||'—')} · <b>Alunos:</b> ${n}</div>
          </div>
          <div style="font-size:11px;font-weight:700;color:var(--azul);text-transform:uppercase;margin-bottom:6px">Disciplinas</div>
          <div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px">
            ${porTurma[tid].map(a=>{const m=getMateria(a.IdMateria);
              return `<span class="badge ${a.Locked?'badge-no':'badge-ok'}">${esc(m?m.Materia:'—')} ${a.Locked?'🔒':''}</span>`;}).join('')}
          </div>
          <div style="display:flex;gap:8px;flex-wrap:wrap">
            <button class="btn btn-primary btn-sm" data-sige-click="${bind((event,element)=>{state.nota.turma=(tid);state.nota.materia='';go('notas')})}">✍️ Lançar Notas</button>
            <button class="btn btn-ghost btn-sm" data-sige-click="${bind((event,element)=>{state.ficha.turma=(tid);state.ficha.materia='';go('ficha-avaliacao')})}">📋 Ficha Avaliação</button>
          </div>
        </div>
      </div>`;
    }).join('')}
  </div>`;
};

/* FICHA DE AVALIAÇÃO — apenas do professor */
VIEWS['ficha-avaliacao'] = el=>{
  if(session.Perfil!=='Professor'){
    el.innerHTML='<div class="card"><div class="vazio">Área para professores.</div></div>'; return;
  }
  const turmas=turmasPermitidas();
  if(!turmas.length){ el.innerHTML='<div class="card"><div class="vazio">Sem turmas.</div></div>'; return; }
  const st=state.ficha;
  if(!st.turma||!turmas.some(t=>t.CodTurma===st.turma)) st.turma=turmas[0].CodTurma;
  const materias=materiasPermitidas(st.turma);
  if(!st.materia||!materias.some(m=>String(m.IdMateria)===String(st.materia))) st.materia=materias[0]?materias[0].IdMateria:null;
  if(!st.periodo) st.periodo='I Trimestre';

  const t=getTurma(st.turma), m=getMateria(st.materia);
  const alunos=t&&m?alunosDaTurma(st.turma,t.Ano):[];

  el.innerHTML=`
  <div class="info-box ok">
    <b>📋 Ficha de Avaliação — Modo Docente:</b> apenas as suas turmas e disciplinas.
  </div>
  <div class="card">
    <div class="card-head"><h2>📋 Filtros</h2></div>
    <div class="card-body"><div class="form-grid g3">
      <div class="campo"><label>Turma</label>
        <select id="fv_turma">${turmas.map(t=>`<option value="${esc(t.CodTurma)}" ${st.turma===t.CodTurma?'selected':''}>${esc(t.CodTurma)} · ${esc(t.Turma)} (${esc(t.Classe)})</option>`).join('')}</select></div>
      <div class="campo"><label>Disciplina</label>
        <select id="fv_mat">${materias.map(m=>`<option value="${m.IdMateria}" ${String(st.materia)===String(m.IdMateria)?'selected':''}>${esc(m.Materia)}</option>`).join('')}</select></div>
      <div class="campo"><label>Período</label>
        <select id="fv_per">${PERIODOS.map(p=>`<option ${st.periodo===p?'selected':''}>${p}</option>`).join('')}</select></div>
    </div></div>
  </div>
  ${t&&m?`
  <div class="card">
    <div class="card-head"><h2>${esc(t.Turma)} · ${esc(m.Materia)} · ${esc(st.periodo)}</h2>
      <button class="btn btn-gold btn-sm" data-sige-click="${bind((event,element)=>{imprimirFichaAvaliacao((st.turma),(st.materia),(st.periodo))})}">🖨 Imprimir</button>
    </div>
    <div class="card-body np"><div class="tabela-wrap"><table class="tabela pauta-tabela">
      <thead><tr><th>#</th><th>Aluno</th><th>MAC</th><th>NPP</th><th>NPT</th><th>Média Trim.</th></tr></thead>
      <tbody>${alunos.map((x,i)=>{
        const reg=getNotaReg(x.ins.IdInscricao,st.materia,t.Ano)||{};
        const perKey=st.periodo.replace(' ','_');
        const tri=reg[perKey]||{MAC:'',NPP:'',NPT:''};
        const mt=mediaTrimestre(reg,perKey);
        return `<tr><td>${i+1}</td>
          <td><b>${esc(x.aluno.Nome)}</b><span class="sub">${esc(x.aluno.IdAluno)}</span></td>
          <td>${tri.MAC!==null&&tri.MAC!==undefined?tri.MAC:'—'}</td>
          <td>${tri.NPP!==null&&tri.NPP!==undefined?tri.NPP:'—'}</td>
          <td>${tri.NPT!==null&&tri.NPT!==undefined?tri.NPT:'—'}</td>
          <td><b class="${mt!==null&&mt>=num(DB.config.notaMinima)?'nota-ok':'nota-bad'}">${mt!==null?mt:'—'}</b></td>
        </tr>`;
      }).join('')}</tbody>
    </table></div></div>
  </div>`:''}`;
  $('#fv_turma').onchange=e=>{st.turma=e.target.value;st.materia='';renderView();};
  $('#fv_mat').onchange=e=>{st.materia=num(e.target.value);renderView();};
  $('#fv_per').onchange=e=>{st.periodo=e.target.value;renderView();};
};

function imprimirFichaAvaliacao(codTurma,idMat,periodo){
  const t=getTurma(codTurma), m=getMateria(idMat);
  if(!t||!m) return;
  const alunos=alunosDaTurma(codTurma,t.Ano);
  const perKey=periodo.replace(' ','_');
  let h=`<div class="prt">${prtHeader()}
    <div class="prt-title">Ficha de Avaliação — Disciplina</div>
    <div class="prt-sub">${esc(t.Turma)} · ${esc(t.Classe)} · ${esc(m.Materia)} · ${esc(periodo)} · Ano ${esc(t.Ano)}</div>
    <table class="prt-tabela"><thead><tr><th>#</th><th>Aluno</th><th class="c">MAC</th><th class="c">NPP</th><th class="c">NPT</th><th class="c">Média Trim.</th></tr></thead>
    <tbody>${alunos.map((x,i)=>{
      const reg=getNotaReg(x.ins.IdInscricao,idMat)||{};
      const tri=reg[perKey]||{MAC:'',NPP:'',NPT:''};
      const mt=mediaTrimestre(reg,perKey);
      return `<tr><td class="c">${i+1}</td><td>${esc(x.aluno.Nome)}</td>
        <td class="c">${tri.MAC!==null&&tri.MAC!==undefined?tri.MAC:'—'}</td>
        <td class="c">${tri.NPP!==null&&tri.NPP!==undefined?tri.NPP:'—'}</td>
        <td class="c">${tri.NPT!==null&&tri.NPT!==undefined?tri.NPT:'—'}</td>
        <td class="c"><b>${mt!==null?mt:'—'}</b></td></tr>`;
    }).join('')}</tbody></table>
    <p style="font-size:11px">Total: ${alunos.length} alunos</p>
    ${prtAss(['O Professor(a)','O Director de Turma','A Direcção Pedagógica'])}
    ${prtFooter()}</div>`;
  imprimir(h,'Ficha Avaliação');
}

