function renderExames(){
  const st=state.exame;
  const t=getTurma(st.turma), m=getMateria(st.materia);
  if(!t||!m){ $('#areaExames').innerHTML='<div class="card"><div class="vazio">Selecione.</div></div>'; return; }
  const alunos=alunosDaTurma(st.turma,t.Ano);
  if(!alunos.length){ $('#areaExames').innerHTML='<div class="card"><div class="vazio">Sem alunos.</div></div>'; return; }
  const rows=alunos.map((x,i)=>{
    const reg=getNotaReg(x.ins.IdInscricao,st.materia)||{};
    const ma=mediaAnual(reg);
    const ef=reg[examField(st.tipo)];
    const nf=notaFinalDisciplina(reg);
    return `<tr>
      <td>${i+1}</td>
      <td><b>${esc(x.aluno.Nome)}</b><span class="sub">${esc(x.aluno.IdAluno)}</span></td>
      <td>${ma!==null?`<b class="${ma>=num(DB.config.notaMinima)?'nota-ok':'nota-bad'}">${ma}</b>`:'—'}</td>
      <td><input class="nota-input" type="number" min="0" max="${DB.config.escalaMax}" step="1"
        data-ins="${x.ins.IdInscricao}" value="${ef!==null&&ef!==undefined?ef:''}" data-sige-input="${bind((event,element)=>{previewExame(element)})}"></td>
      <td class="media-cell">${nf!==null?`<b class="${nf>=num(DB.config.notaMinima)?'nota-ok':'nota-bad'}">${nf}</b>`:'—'}</td>
    </tr>`;
  }).join('');
  $('#areaExames').innerHTML=`<div class="card">
    <div class="card-head"><h2>${esc(t.Turma)} · ${esc(m.Materia)} — ${esc(st.tipo)}</h2></div>
    <div class="card-body np"><div class="tabela-wrap"><table class="tabela pauta-tabela">
      <thead><tr><th>#</th><th>Aluno</th><th>Média Anual</th><th>Nota Exame</th><th>Nota Final</th></tr></thead>
      <tbody>${rows}</tbody>
    </table></div></div>
    <div class="card-body" style="border-top:1px solid var(--linha);display:flex;justify-content:flex-end">
      <button class="btn btn-primary" data-sige-click="${bind((event,element)=>{gravarExames((st.turma),(st.materia),(st.tipo))})}">💾 Gravar Exames</button></div>
  </div>`;
}

function previewExame(inp){
  const insId=inp.dataset.ins;
  const reg=getNotaReg(insId,state.exame.materia)||{};
  const ma=mediaAnual(reg);
  const ef=parseInt(inp.value,10);
  const cell=inp.closest('tr').querySelector('.media-cell');
  if(isNaN(ef)){ cell.innerHTML=ma!==null?`<b class="${ma>=num(DB.config.notaMinima)?'nota-ok':'nota-bad'}">${ma}</b>`:'—'; return; }
  const nf=Math.round((ma||0)*(DB.config.pesoMediaAnual??0.7)+ef*(DB.config.pesoExameFinal??0.3));
  cell.innerHTML=`<b class="${nf>=num(DB.config.notaMinima)?'nota-ok':'nota-bad'}">${nf}</b>`;
}



