function renderRecurso(){
  const st=state.recurso;
  const t=getTurma(st.turma), m=getMateria(st.materia);
  if(!t||!m){ $('#areaRecurso').innerHTML='<div class="card"><div class="vazio">Selecione.</div></div>'; return; }
  const alunos=alunosDaTurma(st.turma,t.Ano);
  const elegiveis=alunos.filter(x=>{
    const reg=getNotaReg(x.ins.IdInscricao,st.materia);
    if(!reg) return false;
    const nf=notaFinalDisciplina(reg);
    return recursoElegivel(x.ins,reg);
  });
  if(!elegiveis.length){ $('#areaRecurso').innerHTML='<div class="card"><div class="vazio"><span class="big">✅</span>Sem elegíveis.</div></div>'; return; }
  const rows=elegiveis.map((x,i)=>{
    const reg=getNotaReg(x.ins.IdInscricao,st.materia);
    const nf=notaFinalDisciplina(reg);
    const rec=reg.ExameRecurso;
    const nfr=notaFinalComRecurso(reg);
    return `<tr>
      <td>${i+1}</td>
      <td><b>${esc(x.aluno.Nome)}</b></td>
      <td><b class="nota-bad">${nf}</b></td>
      <td><input class="nota-input" type="number" min="0" max="${DB.config.escalaMax}" step="1"
        data-ins="${x.ins.IdInscricao}" value="${rec!==null&&rec!==undefined?rec:''}" data-sige-input="${bind((event,element)=>{previewRec(element)})}"></td>
      <td class="media-cell">${nfr!==null?`<b class="${nfr>=num(DB.config.notaMinima)?'nota-ok':'nota-bad'}">${nfr}</b>`:'—'}</td>
    </tr>`;
  }).join('');
  $('#areaRecurso').innerHTML=`<div class="card">
    <div class="card-head"><h2>${esc(t.Turma)} · ${esc(m.Materia)}</h2>
      <span class="badge badge-warn">${elegiveis.length} elegível(is)</span></div>
    <div class="card-body np"><div class="tabela-wrap"><table class="tabela pauta-tabela">
      <thead><tr><th>#</th><th>Aluno</th><th>Nota Final</th><th>Nota Recurso</th><th>Nota c/ Recurso</th></tr></thead>
      <tbody>${rows}</tbody>
    </table></div></div>
    <div class="card-body" style="border-top:1px solid var(--linha);display:flex;justify-content:flex-end">
      <button class="btn btn-primary" data-sige-click="${bind((event,element)=>{gravarRecursos((st.turma),(st.materia))})}">💾 Gravar</button></div>
  </div>`;
}

function previewRec(inp){
  const insId=inp.dataset.ins;
  const reg=getNotaReg(insId,state.recurso.materia)||{};
  const nf=notaFinalDisciplina(reg);
  const rec=parseInt(inp.value,10);
  const cell=inp.closest('tr').querySelector('.media-cell');
  if(isNaN(rec)){ cell.innerHTML=nf!==null?`<b class="${nf>=num(DB.config.notaMinima)?'nota-ok':'nota-bad'}">${nf}</b>`:'—'; return; }
  const nfr=Math.max(nf||0, rec);
  cell.innerHTML=`<b class="${nfr>=num(DB.config.notaMinima)?'nota-ok':'nota-bad'}">${nfr}</b>`;
}



