VIEWS.pautas = el=>{
  const turmas=turmasPermitidas();
  if(!turmas.length){ el.innerHTML='<div class="card"><div class="vazio">Sem turmas.</div></div>'; return; }
  const st=state.pauta;
  if(!st.turma||!turmas.some(t=>t.CodTurma===st.turma)) st.turma=turmas[0].CodTurma;
  if(!st.periodo) st.periodo='I Trimestre';

  el.innerHTML=`
  <div class="card">
    <div class="card-head"><h2>📄 Pauta de Avaliação</h2></div>
    <div class="card-body"><div class="form-grid g3">
      <div class="campo"><label>Turma</label>
        <select id="p_turma">${turmas.map(t=>`<option value="${esc(t.CodTurma)}" ${st.turma===t.CodTurma?'selected':''}>${esc(t.CodTurma)} · ${esc(t.Turma)} (${esc(t.Classe)})</option>`).join('')}</select></div>
      <div class="campo"><label>Período</label>
        <select id="p_per">${PERIODOS.map(p=>`<option ${st.periodo===p?'selected':''}>${p}</option>`).join('')}</select></div>
      <div class="campo"><label>&nbsp;</label>
        <div style="display:flex;gap:8px">
          <button class="btn btn-ghost btn-sm" data-sige-click="${bind((event,element)=>{imprimirPauta((st.turma),(st.periodo))})}">🖨 Pauta</button>
          <button class="btn btn-gold btn-sm" data-sige-click="${bind((event,element)=>{imprimirPautaGeral((st.turma))})}">📊 Pauta Geral</button>
        </div>
      </div>
    </div></div>
  </div>
  <div id="areaPauta"></div>`;
  $('#p_turma').onchange=e=>{st.turma=e.target.value;renderView();};
  $('#p_per').onchange=e=>{st.periodo=e.target.value;renderView();};
  renderPauta();
};

function renderPauta(){
  const st=state.pauta;
  const t=getTurma(st.turma); if(!t){ $('#areaPauta').innerHTML=''; return; }
  const mats=[...new Set(DB.atribuicoes.filter(a=>a.CodTurma===st.turma).map(a=>a.IdMateria))].map(id=>getMateria(id)).filter(Boolean);
  const matsFinal=mats.length?mats:DB.materias.slice(0,8);
  const alunos=alunosDaTurma(st.turma,t.Ano);
  if(!alunos.length){ $('#areaPauta').innerHTML='<div class="card"><div class="vazio">Sem alunos.</div></div>'; return; }
  const perKey=st.periodo.replace(' ','_');
  const rows=alunos.map((x,i)=>{
    const medias=matsFinal.map(m=>mediaTrimestre(getNotaReg(x.ins.IdInscricao,m.IdMateria)||{},perKey));
    const vals=medias.filter(v=>v!==null);
    const mg=vals.length?Math.round(vals.reduce((a,b)=>a+b,0)/vals.length):null;
    return `<tr>
      <td>${i+1}</td>
      <td><b>${esc(x.aluno.Nome)}</b></td>
      ${medias.map(v=>`<td>${v===null?'—':`<b class="${v>=num(DB.config.notaMinima)?'nota-ok':'nota-bad'}">${v}</b>`}</td>`).join('')}
      <td>${mg!==null?`<b class="${mg>=num(DB.config.notaMinima)?'nota-ok':'nota-bad'}">${mg}</b>`:'—'}</td>
    </tr>`;
  }).join('');
  $('#areaPauta').innerHTML=`<div class="card">
    <div class="card-head"><h2>${esc(t.Turma)} · ${esc(t.Classe)} — ${esc(st.periodo)}</h2></div>
    <div class="card-body np"><div class="tabela-wrap"><table class="tabela pauta-tabela">
      <thead><tr><th>#</th><th>Aluno</th>
        ${matsFinal.map(m=>`<th>${esc(m.Sigla||m.Materia.slice(0,4))}</th>`).join('')}
        <th>Média</th></tr></thead>
      <tbody>${rows}</tbody>
    </table></div></div>
  </div>`;
}

