/* DÍVIDAS POR TURMA */
VIEWS.dividas = el=>{
  const anoFiltro=state.ano_divida||DB.config.anoActivo;

  const grupos={};
  DB.inscricoes.filter(i=>i.Ano===anoFiltro && i.Estado!=='Cancelada' && i.Estado!=='Transferido').forEach(i=>{
    const cl=getClasse(i.Classe,i.Ano); if(!cl) return;
    const bill=DB.propinas?.[i.IdInscricao]||{};
    const falta=bill.mesesEmFalta||0;
    if(falta<=0) return;
    const key=(i.CodCurso||i.Curso)+'|'+i.Classe+'|'+(i.Turma||'');
    if(!grupos[key]) grupos[key]={curso:i.CodCurso||i.Curso,classe:i.Classe,turma:i.Turma,codTurma:i.CodTurma,alunos:[]};
    grupos[key].alunos.push({ins:i,aluno:getAluno(i.CodAluno),cl,falta,valor:bill.divida||0});
  });

  const gruposArr=Object.values(grupos).sort((a,b)=>{
    if(a.curso!==b.curso) return String(a.curso).localeCompare(String(b.curso));
    if(a.classe!==b.classe) return String(a.classe).localeCompare(String(b.classe));
    return String(a.turma).localeCompare(String(b.turma));
  });
  const totalGeral=gruposArr.reduce((s,g)=>s+g.alunos.reduce((ss,x)=>ss+x.valor,0),0);
  const totalAlunos=gruposArr.reduce((s,g)=>s+g.alunos.length,0);

  el.innerHTML=`
  <div class="toolbar">
    <select id="d_ano">
      ${[...new Set(DB.inscricoes.map(i=>i.Ano).concat(DB.anosLectivos.map(a=>a.Ano)))].sort().reverse().map(a=>`<option ${a===anoFiltro?'selected':''}>${esc(a)}</option>`).join('')}
    </select>
    <div class="spacer"></div>
    <button class="btn btn-ghost" data-sige-click="${bind((event,element)=>{imprimirDividas((anoFiltro))})}">🖨 Imprimir Lista</button>
  </div>
  <div class="stats">
    <div class="stat r"><div class="ico">⚠️</div><div><b>${totalAlunos}</b><span>Alunos Devedores</span></div></div>
    <div class="stat r"><div class="ico">💰</div><div><b style="font-size:18px">${money(totalGeral)}</b><span>Total em Dívida</span></div></div>
    <div class="stat o"><div class="ico">🏫</div><div><b>${gruposArr.length}</b><span>Grupos</span></div></div>
  </div>
  ${gruposArr.length?gruposArr.map(g=>{
    const cur=getCurso(g.curso);
    return `<div class="card">
      <div class="card-head">
        <h2>${esc(cur?cur.Nome:g.curso)} · ${esc(g.classe)} · Turma ${esc(g.turma||'—')}</h2>
        <span class="badge badge-no">${g.alunos.length} aluno(s)</span>
        <span class="badge badge-warn">${money(g.alunos.reduce((s,x)=>s+x.valor,0))}</span>
      </div>
      <div class="card-body np"><div class="tabela-wrap"><table class="tabela">
        <thead><tr><th>#</th><th>Nº Processo</th><th>Nome</th><th>Sexo</th><th>Idade</th><th>Meses em Falta</th><th>Valor em Dívida</th></tr></thead>
        <tbody>${g.alunos.map((x,i)=>`<tr>
          <td>${i+1}</td>
          <td>${esc(x.aluno.IdAluno)}</td>
          <td><b>${esc(x.aluno.Nome)}</b></td>
          <td>${x.aluno.Sexo}</td>
          <td>${idade(x.aluno.DataNa)}</td>
          <td><span class="badge badge-warn">${x.falta} mês(es)</span></td>
          <td><b style="color:var(--vermelho)">${money(x.valor)}</b></td>
        </tr>`).join('')}</tbody>
      </table></div></div>
    </div>`;
  }).join(''):'<div class="card"><div class="vazio"><span class="big">✅</span>Nenhum aluno com propinas em atraso.</div></div>'}`;
  const s=$('#d_ano'); if(s) s.onchange=e=>{state.ano_divida=e.target.value;renderView();};
};

/* EXPORTAÇÃO */
VIEWS.exportar = el=>{
  const anoFiltro=state.ano_exp||DB.config.anoActivo;
  const elegiveis=DB.inscricoes
    .filter(i=>i.Ano===anoFiltro && i.Estado==='Pendente')
    .map(i=>({ins:i, aluno:getAluno(i.CodAluno)}))
    .filter(x=>x.aluno)
    .filter(x=>alunoAvaliado(x.ins.IdInscricao))
    .filter(x=>propinasEmDia(x.ins.CodAluno, x.ins.Ano));

  const grupos={};
  elegiveis.forEach(x=>{
    const key=(x.ins.CodCurso||x.ins.Curso)+'|'+x.ins.Classe+'|'+(x.ins.Turma||'');
    if(!grupos[key]) grupos[key]={curso:x.ins.CodCurso||x.ins.Curso,classe:x.ins.Classe,turma:x.ins.Turma,codTurma:x.ins.CodTurma,alunos:[]};
    grupos[key].alunos.push(x);
  });
  const gruposArr=Object.values(grupos).sort((a,b)=>{
    if(a.curso!==b.curso) return String(a.curso).localeCompare(String(b.curso));
    if(a.classe!==b.classe) return String(a.classe).localeCompare(String(b.classe));
    return String(a.turma).localeCompare(String(b.turma));
  });

  el.innerHTML=`
  <div class="info-box ok">
    <b>📤 Exportação:</b> apenas alunos <b>(1)</b> avaliados em todas as disciplinas do ano de origem,
    <b>(2)</b> com <b>propinas do ano de origem em dia</b> e <b>(3)</b> em estado <b>Pendente</b>, aguardando confirmação.
  </div>
  <div class="toolbar">
    <select id="ex_ano">
      ${[...new Set(DB.inscricoes.map(i=>i.Ano).concat(DB.anosLectivos.map(a=>a.Ano)))].sort().reverse().map(a=>`<option ${a===anoFiltro?'selected':''}>${esc(a)}</option>`).join('')}
    </select>
    <div class="spacer"></div>
    <button class="btn btn-ghost" data-sige-click="${bind((event,element)=>{exportarElegiveisCSV((anoFiltro))})}">⬇ CSV</button>
    <button class="btn btn-ghost" data-sige-click="${bind((event,element)=>{imprimirListaExportar((anoFiltro))})}">🖨 Imprimir Lista</button>
    ${canEdit('confirmar_matricula')?`<button class="btn btn-ok" data-sige-click="${bind((event,element)=>{confirmarTodosElegiveis((anoFiltro))})}">✓ Confirmar Todas</button>`:''}
  </div>
  ${gruposArr.length?gruposArr.map(g=>{
    const cur=getCurso(g.curso);
    return `<div class="card">
      <div class="card-head">
        <h2>${esc(cur?cur.Nome:g.curso)} · ${esc(g.classe)} · Turma ${esc(g.turma||'—')}</h2>
        <span class="badge badge-ok">${g.alunos.length} aluno(s)</span>
      </div>
      <div class="card-body np"><div class="tabela-wrap"><table class="tabela">
        <thead><tr><th>#</th><th>Nº Processo</th><th>Nome</th><th>Sexo</th><th>Idade</th><th>Situação</th><th style="text-align:right">Acções</th></tr></thead>
        <tbody>${g.alunos.map((x,i)=>{
          const sit=situacaoAluno(x.ins.IdInscricao);
          return `<tr>
            <td>${i+1}</td>
            <td>${esc(x.aluno.IdAluno)}</td>
            <td><b>${esc(x.aluno.Nome)}</b></td>
            <td>${x.aluno.Sexo}</td>
            <td>${idade(x.aluno.DataNa)}</td>
            <td>${sit?`<span class="badge ${sit.situacao==='Aprovado'?'badge-ok':sit.situacao==='Recurso'?'badge-warn':'badge-no'}">${sit.situacao}</span>`:'—'}</td>
            <td class="acoes">${canEdit('confirmar_matricula')?`<button class="btn btn-ok btn-xs" data-sige-click="${bind((event,element)=>{confirmarMatricula((x.ins.IdInscricao))})}">✓ Confirmar</button>`:''}</td>
          </tr>`;
        }).join('')}</tbody>
      </table></div></div>
    </div>`;
  }).join(''):'<div class="card"><div class="vazio"><span class="big">📭</span>Nenhum aluno cumpre os critérios.</div></div>'}`;
  const s=$('#ex_ano'); if(s) s.onchange=e=>{state.ano_exp=e.target.value;renderView();};
};



function confirmarTodosElegiveis(anoLectivo){
  const elegiveis=DB.inscricoes
    .filter(i=>i.Ano===anoLectivo && i.Estado==='Pendente')
    .filter(i=>alunoAvaliado(i.IdInscricao))
    .filter(i=>propinasEmDia(i.CodAluno, i.Ano));
  if(!elegiveis.length){ toast('Sem elegíveis','warn'); return; }
  confirmar(`Confirmar <b>${elegiveis.length}</b> matrículas elegíveis em <b>${anoLectivo}</b>?`,()=>{
    elegiveis.forEach(i=>{ i.Estado='Matriculado'; });
    registrarLog('confirmar_lote',`${elegiveis.length} matrículas ${anoLectivo}`);
    saveDB(); renderView(); toast(`${elegiveis.length} confirmada(s).`);
  },'✓ Confirmar Todas',false);
}

