function emitirDocumento(tipo){
  const idAluno=$('#doc_aluno').value;
  const a=getAluno(idAluno);
  if(!a){ toast('Selecione um aluno','err'); return; }
  DB.documentosEmitidos.push({
    Id:nextId(DB.documentosEmitidos,'Id'),
    Data:now(),Tipo:tipo,Aluno:a.Nome,CodAluno:idAluno,Usuario:session.Nome
  });
  saveDB();
  if(tipo==='ficha') imprimirFichaAluno(idAluno);
  else if(tipo==='boletim'){
    const ins=DB.inscricoes.find(i=>i.CodAluno===idAluno && i.Ano===DB.config.anoActivo);
    if(!ins){ toast('Sem matrícula activa','err'); return; }
    imprimirBoletim(ins.IdInscricao);
  }
  else if(tipo==='declaracao') imprimirDeclaracao(idAluno);
  else if(tipo==='certificado') imprimirCertificado(idAluno);
  else if(tipo==='diploma') imprimirDiploma(idAluno);
  else if(tipo==='atestado') imprimirAtestado(idAluno);
  toast('Documento gerado.');
  setTimeout(()=>renderView(),500);
}

