function guardarConfig(){
  const g=k=>{const el=$('#cfg_'+k); return el?el.value.trim():'';};
  ['ministerio','escolaNome','escolaNIF','escolaTelefone','escolaEndereco','escolaMunicipio','escolaEmail','escolaDiretor','anoActivo']
    .forEach(k=>DB.config[k]=g(k));
  DB.config.notaMinima=num(g('notaMinima'))||10;
  DB.config.pesoMediaAnual=num(g('pesoMediaAnual'));
  DB.config.pesoExameFinal=num(g('pesoExameFinal'));
  saveDB(); $('#anoChip').textContent='Ano Lectivo '+DB.config.anoActivo;
  toast('Guardado.');
}

