function imprimirPauta(idTurma,periodo){
 if(session.Perfil==='Professor')throw new Error('O professor só pode emitir a ficha da sua disciplina.');
  const t=getTurma(idTurma); if(!t) return;
  const mats=[...new Set(DB.atribuicoes.filter(a=>a.CodTurma===idTurma).map(a=>a.IdMateria))].map(id=>getMateria(id)).filter(Boolean);
  const matsFinal=mats.length?mats:DB.materias.slice(0,8);
  const alunos=alunosDaTurma(idTurma,t.Ano); const perKey=periodo.replace(' ','_');
  let h=`<div class="prt">${prtHeader()}
    <div class="prt-title">Pauta de Avaliação</div>
    <div class="prt-sub">${esc(t.Turma)} · ${esc(t.Classe)} · ${esc(periodo)} · ${esc(t.Ano)}</div>
    <table class="prt-tabela"><thead><tr><th>#</th><th>Aluno</th>
      ${matsFinal.map(m=>`<th class="c">${esc(m.Sigla||m.Materia.slice(0,3).toUpperCase())}</th>`).join('')}
      <th class="c">Média</th></tr></thead>
    <tbody>${alunos.map((x,i)=>{
      const medias=matsFinal.map(m=>mediaTrimestre(getNotaReg(x.ins.IdInscricao,m.IdMateria)||{},perKey));
      const vals=medias.filter(v=>v!==null);
      const mg=vals.length?Math.round(vals.reduce((a,b)=>a+b,0)/vals.length):null;
      return `<tr><td class="c">${i+1}</td><td>${esc(x.aluno.Nome)}</td>
        ${medias.map(v=>`<td class="c">${v===null?'—':v}</td>`).join('')}
        <td class="c"><b>${mg!==null?mg:'—'}</b></td></tr>`;
    }).join('')}</tbody></table>
    <p style="font-size:10.5px"><b>Legenda:</b> ${matsFinal.map(m=>esc(m.Sigla||'')+'='+esc(m.Materia)).join(' · ')}</p>
    ${prtAss(['O Professor(a)','O Director de Turma','A Direcção Pedagógica'])}
    ${prtFooter()}</div>`;
  imprimir(h,'Pauta '+t.Turma+' '+periodo);
}

